  void emitEnded({String? path}) {
    final p = path ?? _currentPath;
    _events.add(TransportEndedEvent(path: p));
  }

  void reset() {
    outcomesByPath.clear();
    _currentPath = null;
    _playing = false;
    _position = Duration.zero;
  }
}
